create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users on delete cascade,display_name text not null,avatar_url text,role text not null default 'member' check(role in('member','moderator','admin')),interests text[] not null default array['fishing','surfing','kayaking'],country text,city text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audience_contacts(user_id uuid primary key references public.profiles on delete cascade,email text not null unique,plan text not null default 'free' check(plan in('free','plus','pro')),subscription_status text not null default 'active',stripe_customer_id text unique,stripe_subscription_id text unique,marketing_consent boolean not null default false,marketing_consent_at timestamptz,marketing_source text not null default 'website_signup',lifecycle_stage text not null default 'member',last_seen_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.community_messages(id uuid primary key default gen_random_uuid(),channel text not null check(channel in('fishing','surfing','kayaking')),author_id uuid not null references public.profiles on delete cascade,parent_id uuid references public.community_messages on delete cascade,content text not null default '' check(char_length(content)<=3000),created_at timestamptz not null default now());
create table public.community_reactions(message_id uuid references public.community_messages on delete cascade,user_id uuid references public.profiles on delete cascade,emoji text not null check(char_length(emoji)between 1 and 16),created_at timestamptz not null default now(),primary key(message_id,user_id,emoji));
create table public.community_attachments(id uuid primary key default gen_random_uuid(),message_id uuid not null references public.community_messages on delete cascade,owner_id uuid not null references public.profiles on delete cascade,storage_path text not null unique,public_url text not null,file_name text not null,mime_type text not null check(mime_type in('image/jpeg','image/png','image/webp','image/gif')),size_bytes bigint not null check(size_bytes between 1 and 8388608),created_at timestamptz not null default now());
create index idx_audience_marketing on public.audience_contacts(marketing_consent,created_at desc)where marketing_consent=true;create index idx_messages_channel_created on public.community_messages(channel,created_at desc);create index idx_messages_parent on public.community_messages(parent_id,created_at)where parent_id is not null;create index idx_reactions_message on public.community_reactions(message_id);create index idx_attachments_message on public.community_attachments(message_id);
create or replace function public.new_member()returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name)values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'display_name'),''),split_part(coalesce(new.email,'Member'),'@',1)));insert into public.audience_contacts(user_id,email,marketing_consent,marketing_consent_at)values(new.id,coalesce(new.email,''),coalesce((new.raw_user_meta_data->>'marketing_consent')::boolean,false),case when coalesce((new.raw_user_meta_data->>'marketing_consent')::boolean,false)then now()else null end);return new;end;$$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.new_member();
alter table public.profiles enable row level security;alter table public.audience_contacts enable row level security;alter table public.community_messages enable row level security;alter table public.community_reactions enable row level security;alter table public.community_attachments enable row level security;
revoke all on public.profiles,public.audience_contacts,public.community_messages,public.community_reactions,public.community_attachments from anon;grant select on public.profiles to authenticated;grant update(display_name,avatar_url,interests,country,city,updated_at)on public.profiles to authenticated;grant select on public.audience_contacts to authenticated;grant update(marketing_consent,marketing_consent_at,updated_at)on public.audience_contacts to authenticated;grant select,insert,update,delete on public.community_messages to authenticated;grant select,insert,delete on public.community_reactions,public.community_attachments to authenticated;
create policy "member profiles" on public.profiles for select to authenticated using(true);create policy "own profile" on public.profiles for update to authenticated using(id=auth.uid())with check(id=auth.uid());create policy "own or admin contact" on public.audience_contacts for select to authenticated using(user_id=auth.uid()or exists(select 1 from public.profiles where id=auth.uid()and role='admin'));create policy "own consent" on public.audience_contacts for update to authenticated using(user_id=auth.uid())with check(user_id=auth.uid());
create policy "read messages" on public.community_messages for select to authenticated using(true);create policy "create messages" on public.community_messages for insert to authenticated with check(author_id=auth.uid());create policy "edit own messages" on public.community_messages for update to authenticated using(author_id=auth.uid())with check(author_id=auth.uid());create policy "delete own messages" on public.community_messages for delete to authenticated using(author_id=auth.uid()or exists(select 1 from public.profiles where id=auth.uid()and role in('moderator','admin')));create policy "read reactions" on public.community_reactions for select to authenticated using(true);create policy "add own reaction" on public.community_reactions for insert to authenticated with check(user_id=auth.uid());create policy "delete own reaction" on public.community_reactions for delete to authenticated using(user_id=auth.uid());create policy "read attachments" on public.community_attachments for select to authenticated using(true);create policy "add own attachment" on public.community_attachments for insert to authenticated with check(owner_id=auth.uid());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('community-media','community-media',true,8388608,array['image/jpeg','image/png','image/webp','image/gif']);create policy "read community media" on storage.objects for select using(bucket_id='community-media');create policy "upload community media" on storage.objects for insert to authenticated with check(bucket_id='community-media'and(storage.foldername(name))[1]=auth.uid()::text);create policy "delete own community media" on storage.objects for delete to authenticated using(bucket_id='community-media'and(storage.foldername(name))[1]=auth.uid()::text);
alter publication supabase_realtime add table public.community_messages;alter publication supabase_realtime add table public.community_reactions;
